n += clamp01(texture(sampler_pw_main, uv+d*vec2( 0.0 ,-1)).x * 999.0);
n += clamp01(texture(sampler_pw_main, uv+d*vec2(-1, 1.0 )).x * 999.0);
n += clamp01(texture(sampler_pw_main, uv+d*vec2(-1, 0.0 )).x * 999.0);
n += clamp01(texture(sampler_pw_main, uv+d*vec2(-1,-1)).x * 999.0);
